const insertDirectConversation = `-- name: InsertDirectConversation :one

INSERT INTO conversations (
    company_id, kind, agent_id, created_by_user_id, title, request_key, pinned_at
)
SELECT
    companies.id,
    'direct',
    agents.id,
    actor_membership.user_id,
    $1::text,
    $2::uuid,
    CASE
        WHEN agents.reports_to_agent_id IS NULL
          AND NOT EXISTS (
              SELECT 1
              FROM conversations AS existing
              WHERE existing.company_id = companies.id
                AND existing.kind = 'direct'
                AND existing.document_thread_id IS NULL
                AND existing.agent_id = agents.id
                AND existing.created_by_user_id = actor_membership.user_id
                AND existing.archived_at IS NULL
          )
        THEN clock_timestamp()
        ELSE NULL
    END
FROM companies
JOIN company_members AS actor_membership
  ON actor_membership.company_id = companies.id
 AND actor_membership.user_id = $3::uuid
 AND actor_membership.status = 'active'
JOIN agents
  ON agents.company_id = companies.id
 AND agents.id = $4::uuid
 AND agents.archived_at IS NULL
WHERE companies.id = $5::uuid
  AND companies.deleting_at IS NULL
ON CONFLICT DO NOTHING
RETURNING conversations.id, conversations.company_id, conversations.kind, conversations.task_id, conversations.schedule_id, conversations.agent_id, conversations.created_by_user_id, conversations.title, conversations.request_key, conversations.pinned_at, conversations.archived_at, conversations.created_at, conversations.updated_at, conversations.version, conversations.head_seq, conversations.is_general, conversations.channel_id, conversations.channel_execution_generation, conversations.channel_context_revision, conversations.project_id, conversations.document_thread_id
`

