const updateDirectConversationUserState = `-- name: UpdateDirectConversationUserState :one
WITH statement_clock AS MATERIALIZED (
    SELECT clock_timestamp()::timestamptz AS now_at
)
UPDATE conversations
SET pinned_at = CASE
        WHEN $1::boolean
            THEN COALESCE(conversations.pinned_at, statement_clock.now_at)
        ELSE NULL
    END,
    archived_at = CASE
        WHEN $2::boolean
            THEN COALESCE(conversations.archived_at, statement_clock.now_at)
        ELSE NULL
    END,
    -- Filing a legacy default chat turns it into an independent session so
    -- restoring it can coexist with a newer default chat for the same Agent.
    request_key = CASE
        WHEN conversations.request_key IS NULL
          AND ($2::boolean OR conversations.archived_at IS NOT NULL)
            THEN gen_random_uuid()
        ELSE conversations.request_key
    END,
    updated_at = statement_clock.now_at,
    version = conversations.version + 1
FROM companies, company_members AS actor_membership, statement_clock
WHERE conversations.id = $3::uuid
  AND conversations.company_id = $4::uuid
  AND conversations.kind = 'direct'
  AND conversations.created_by_user_id = $5::uuid
  AND conversations.version = $6::bigint
  AND companies.id = conversations.company_id
  AND companies.deleting_at IS NULL
  AND actor_membership.company_id = conversations.company_id
  AND actor_membership.user_id = $5::uuid
  AND actor_membership.status = 'active'
  AND (
      $1::boolean <> (conversations.pinned_at IS NOT NULL)
      OR $2::boolean <> (conversations.archived_at IS NOT NULL)
  )
RETURNING conversations.id, conversations.company_id, conversations.kind, conversations.task_id, conversations.schedule_id, conversations.agent_id, conversations.created_by_user_id, conversations.title, conversations.request_key, conversations.pinned_at, conversations.archived_at, conversations.created_at, conversations.updated_at, conversations.version, conversations.head_seq, conversations.is_general, conversations.channel_id, conversations.channel_execution_generation, conversations.channel_context_revision, conversations.project_id, conversations.document_thread_id
`

